import{_ as o,C as n,c as r,o as i,a3 as t,G as s}from"./chunks/framework.Dokpd4od.js";const _=JSON.parse('{"title":"Inventory settings","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/inventories/get-started/inventory-settings.md","filePath":"master/supply-chain/inventories/get-started/inventory-settings.md","lastUpdated":1791902625000}'),d={name:"master/supply-chain/inventories/get-started/inventory-settings.md"};function l(g,e,c,u,p,h){const a=n("ImagePopup");return i(),r("div",null,[e[0]||(e[0]=t('<h1 id="inventory-settings" tabindex="-1">Inventory settings <a class="header-anchor" href="#inventory-settings" aria-label="Permalink to &quot;Inventory settings&quot;">​</a></h1><p>Settings decide which parts of Inventory are switched on. A small shop may need only products and receipts. A larger one adds locations, lots, packages and multi step routes. Turn on only what you use, because every option adds menus and fields.</p><blockquote><p><strong>In simple words:</strong> Settings are switches. Each one shows or hides a part of Inventory.</p></blockquote><p>Go to <code>Inventory → Settings</code>. The left list holds five pages: <strong>Manage Operations</strong>, <strong>Manage Products</strong>, <strong>Manage Warehouses</strong>, <strong>Manage Traceability</strong> and <strong>Manage Logistics</strong>. Every page has a <strong>Save changes</strong> button. Toggle an option, then click <strong>Save changes</strong>.</p><h2 id="manage-operations" tabindex="-1">Manage Operations <a class="header-anchor" href="#manage-operations" aria-label="Permalink to &quot;Manage Operations&quot;">​</a></h2><p><code>Inventory → Settings → Manage Operations</code></p>',6)),s(a,{src:"/images1/inventory/set_manage_operations.png",alt:"Manage Operations settings page with Packages on and the annual inventory day and month"}),e[1]||(e[1]=t('<ul><li><strong>Packages:</strong> Put products in packs, such as parcels or boxes, and track them. Turns on <code>Inventory → Products → Packages</code> and <code>Configurations → Package Types</code>. A <strong>Configure Packages</strong> link opens the list.</li><li><strong>Annual Inventory Day</strong> (required): The day of the month for your yearly count. Example: 31.</li><li><strong>Annual Inventory Month</strong> (required): The month for your yearly count. Example: December.</li></ul><p>The day and month fill the default <strong>Scheduled At</strong> date on count lines, for example Dec 31.</p><h2 id="manage-products" tabindex="-1">Manage Products <a class="header-anchor" href="#manage-products" aria-label="Permalink to &quot;Manage Products&quot;">​</a></h2><p><code>Inventory → Settings → Manage Products</code></p>',4)),s(a,{src:"/images1/inventory/set_manage_products.png",alt:"Manage Products settings page with Variants, Unit of Measure and Packagings on"}),e[2]||(e[2]=t('<ul><li><strong>Variants:</strong> Give products attributes such as colour or size. Turns on <code>Configurations → Attributes</code>.</li><li><strong>Unit of Measure:</strong> Buy and sell in different units. Turns on <code>Configurations → UOM Categories</code> and unit fields.</li><li><strong>Packagings:</strong> Define pack sizes, such as a pack of 10. Turns on <code>Configurations → Packagings</code>. A <strong>Configure Packagings</strong> link opens the list.</li></ul><h2 id="manage-warehouses" tabindex="-1">Manage Warehouses <a class="header-anchor" href="#manage-warehouses" aria-label="Permalink to &quot;Manage Warehouses&quot;">​</a></h2><p><code>Inventory → Settings → Manage Warehouses</code></p>',3)),s(a,{src:"/images1/inventory/set_manage_warehouses.png",alt:"Manage Warehouses settings page with Locations and Multi Steps Routes on"}),e[3]||(e[3]=t('<ul><li><strong>Locations:</strong> Track where products sit inside the warehouse. Turns on <code>Configurations → Locations</code> and location fields on transfers and operation types.</li><li><strong>Multi Steps Routes:</strong> Use your own routes to move products between steps and warehouses. Turns on <strong>Routes</strong> and <strong>Rules</strong>, and shows the <strong>Settings</strong> block on a warehouse where you pick one, two or three steps.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>You cannot turn off the multi location option when you have more than one warehouse. Save shows a warning and keeps it on.</p></div><h2 id="manage-traceability" tabindex="-1">Manage Traceability <a class="header-anchor" href="#manage-traceability" aria-label="Permalink to &quot;Manage Traceability&quot;">​</a></h2><p><code>Inventory → Settings → Manage Traceability</code></p>',4)),s(a,{src:"/images1/inventory/set_manage_traceability.png",alt:"Manage Traceability settings page with Lots and Serial Numbers on"}),e[4]||(e[4]=t('<ul><li><strong>Lots &amp; Serial Numbers:</strong> Trace products from vendor to customer. Turns on <code>Products → Lots / Serial Numbers</code> and the <strong>Track By</strong> field on products.</li><li><strong>Display on Delivery Slips:</strong> Shows only when lots are on. Prints lot and serial numbers on the delivery slip.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Before you turn off <strong>Lots &amp; Serial Numbers</strong>, switch off tracking on every product that still has stock with lots or serials. Otherwise Save shows an error and the setting stays on.</p></div><h2 id="manage-logistics" tabindex="-1">Manage Logistics <a class="header-anchor" href="#manage-logistics" aria-label="Permalink to &quot;Manage Logistics&quot;">​</a></h2><p><code>Inventory → Settings → Manage Logistics</code></p>',4)),s(a,{src:"/images1/inventory/set_manage_logistics.png",alt:"Manage Logistics settings page with Dropshipping on"}),e[5]||(e[5]=t('<ul><li><strong>Dropshipping:</strong> Let a vendor ship straight to your customer. Turns on <code>Operations → Dropships</code>. When a product is set to dropship, confirming the sales order creates a request for quotation. The customer address replaces the warehouse address.</li></ul><h2 id="quick-table" tabindex="-1">Quick table <a class="header-anchor" href="#quick-table" aria-label="Permalink to &quot;Quick table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Page</th><th>Reveals</th></tr></thead><tbody><tr><td>Packages</td><td>Manage Operations</td><td>Packages, Package Types</td></tr><tr><td>Variants</td><td>Manage Products</td><td>Attributes</td></tr><tr><td>Unit of Measure</td><td>Manage Products</td><td>UOM Categories</td></tr><tr><td>Packagings</td><td>Manage Products</td><td>Packagings</td></tr><tr><td>Locations</td><td>Manage Warehouses</td><td>Locations</td></tr><tr><td>Multi Steps Routes</td><td>Manage Warehouses</td><td>Routes, Rules, warehouse steps</td></tr><tr><td>Lots &amp; Serial Numbers</td><td>Manage Traceability</td><td>Lots, Track By</td></tr><tr><td>Dropshipping</td><td>Manage Logistics</td><td>Dropships</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Turn settings on before you create records that depend on them. For example, enable <strong>Lots &amp; Serial Numbers</strong> before you receive tracked products.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./inventory-overview.html">Inventory overview</a></li><li><a href="./../tracking/lots-and-serial-numbers.html">Lots and serial numbers</a></li><li><a href="./../tracking/packages.html">Packages</a></li><li><a href="./../products/units-of-measure.html">Units of measure</a></li><li><a href="./../warehouses/warehouses.html">Warehouses</a></li></ul>',6))])}const y=o(d,[["render",l]]);export{_ as __pageData,y as default};
